Q: Edit and create HTML file using Python A: <p>&lt;!DOCTYPE html&gt;</p>
<p>&lt;html lang=&quot;id&quot;&gt;</p>
<p>&lt;head&gt;</p>
<p>&lt;meta charset=&quot;UTF-8&quot;&gt;</p>
<p>&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;</p>
<p>&lt;title&gt;Toko Online Sederhana&lt;/title&gt;</p>
<p>&lt;script src=&quot;https://cdn.tailwindcss.com&quot;&gt;&lt;/script&gt;</p>
<p>&lt;/head&gt;</p>
<p>&lt;body class=&quot;bg-gray-100 font-sans&quot;&gt;</p>
<p>&lt;!-- Header --&gt;</p>
<p>&lt;header class=&quot;bg-blue-600 text-white p-4 sticky top-0 shadow-md&quot;&gt;</p>
<pre><code>\&lt;div class=&quot;container mx-auto flex justify-between items-center&quot;\&gt;

  \&lt;h1 class=&quot;text-xl font-bold&quot;\&gt;TokoOnlineKU\&lt;/h1\&gt;

  \&lt;button onclick=&quot;toggleCart()&quot; class=&quot;bg-blue-800 px-4 py-2 rounded-lg relative&quot;\&gt;

    🛒 Keranjang (\&lt;span id=&quot;cart-count&quot;\&gt;0\&lt;/span\&gt;)

  \&lt;/button\&gt;

\&lt;/div\&gt;
</code></pre>
<p>&lt;/header&gt;</p>
<p>&lt;!-- Product Catalog --&gt;</p>
<p>&lt;main class=&quot;container mx-auto p-6&quot;&gt;</p>
<pre><code>\&lt;h2 class=&quot;text-2xl font-semibold mb-6&quot;\&gt;Katalog Produk\&lt;/h2\&gt;

\&lt;div id=&quot;product-list&quot; class=&quot;grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6&quot;\&gt;\&lt;/div\&gt;
</code></pre>
<p>&lt;/main&gt;</p>
<p>&lt;!-- Sidebar Cart --&gt;</p>
<p>&lt;div id=&quot;cart-sidebar&quot; class=&quot;fixed top-0 right-0 w-80 h-full bg-white shadow-xl transform translate-x-full transition-transform duration-300 p-6 overflow-y-auto&quot;&gt;</p>
<pre><code>\&lt;div class=&quot;flex justify-between items-center mb-4&quot;\&gt;

  \&lt;h3 class=&quot;text-xl font-bold&quot;\&gt;Keranjang Belanja\&lt;/h3\&gt;

  \&lt;button onclick=&quot;toggleCart()&quot; class=&quot;text-gray-500 font-bold&quot;\&gt;✕\&lt;/button\&gt;

\&lt;/div\&gt;

\&lt;div id=&quot;cart-items&quot; class=&quot;space-y-4 mb-4&quot;\&gt;\&lt;/div\&gt;

\&lt;hr class=&quot;my-4&quot;\&gt;

\&lt;div class=&quot;flex justify-between font-bold text-lg mb-4&quot;\&gt;

  \&lt;span\&gt;Total:\&lt;/span\&gt;

  \&lt;span id=&quot;cart-total&quot;\&gt;Rp 0\&lt;/span\&gt;

\&lt;/div\&gt;

\&lt;button onclick=&quot;checkoutWhatsApp()&quot; class=&quot;w-full bg-green-500 hover:bg-green-600 text-white py-2 rounded-lg font-semibold&quot;\&gt;

  Beli via WhatsApp

\&lt;/button\&gt;
</code></pre>
<p>&lt;/div&gt;</p>
<p>&lt;script&gt;</p>
<pre><code>const products = \[

  { id: 1, name: &quot;Kaos Polos Cotton 30s&quot;, price: 55000, img: &quot;https://via.placeholder.com/150&quot; },

  { id: 2, name: &quot;Sepatu Sneaker Casual&quot;, price: 210000, img: &quot;https://via.placeholder.com/150&quot; },

  { id: 3, name: &quot;Tas Ransel Laptop&quot;, price: 145000, img: &quot;https://via.placeholder.com/150&quot; }

\];

let cart = \[\];

function renderProducts() {

  const container = document.getElementById(&quot;product-list&quot;);

  container.innerHTML = products.map(p =\&gt; \`

    \&lt;div class=&quot;bg-white p-4 rounded-xl shadow-sm border border-gray-200&quot;\&gt;

      \&lt;img src=&quot;${p.img}&quot; alt=&quot;${p.name}&quot; class=&quot;w-full h-40 object-cover rounded-md mb-4&quot;\&gt;

      \&lt;h3 class=&quot;font-bold text-lg mb-1&quot;\&gt;${p.name}\&lt;/h3\&gt;

      \&lt;p class=&quot;text-blue-600 font-semibold mb-4&quot;\&gt;Rp ${p.price.toLocaleString('id-ID')}\&lt;/p\&gt;

      \&lt;button onclick=&quot;addToCart(${p.id})&quot; class=&quot;w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700&quot;\&gt;

        + Keranjang

      \&lt;/button\&gt;

    \&lt;/div\&gt;

  \`).join('');

}

function addToCart(productId) {

  const product = products.find(p =\&gt; p.id === productId);

  const exist = cart.find(item =\&gt; item.id === productId);

  if (exist) {

    exist.qty++;

  } else {

    cart.push({ ...product, qty: 1 });

  }

  updateCart();

}

function updateCart() {

  const cartItems = document.getElementById(&quot;cart-items&quot;);

  const cartCount = document.getElementById(&quot;cart-count&quot;);

  const cartTotal = document.getElementById(&quot;cart-total&quot;);

  cartCount.innerText = cart.reduce((acc, item) =\&gt; acc + item.qty, 0);

  cartItems.innerHTML = cart.length === 0 

    ? '\&lt;p class=&quot;text-gray-500&quot;\&gt;Keranjang masih kosong.\&lt;/p\&gt;' 

    : cart.map(item =\&gt; \`

      \&lt;div class=&quot;flex justify-between items-center text-sm&quot;\&gt;

        \&lt;div\&gt;

          \&lt;p class=&quot;font-semibold&quot;\&gt;${item.name}\&lt;/p\&gt;

          \&lt;p class=&quot;text-gray-500&quot;\&gt;${item.qty} x Rp ${item.price.toLocaleString('id-ID')}\&lt;/p\&gt;

        \&lt;/div\&gt;

        \&lt;button onclick=&quot;removeFromCart(${item.id})&quot; class=&quot;text-red-500 font-bold&quot;\&gt;Hapus\&lt;/button\&gt;

      \&lt;/div\&gt;

    \`).join('');

  const total = cart.reduce((acc, item) =\&gt; acc + (item.price \* item.qty), 0);

  cartTotal.innerText = \`Rp ${total.toLocaleString('id-ID')}\`;

}

function removeFromCart(id) {

  cart = cart.filter(item =\&gt; item.id !== id);

  updateCart();

}

function toggleCart() {

  document.getElementById(&quot;cart-sidebar&quot;).classList.toggle(&quot;translate-x-full&quot;);

}

function checkoutWhatsApp() {

  if (cart.length === 0) return alert(&quot;Keranjang belanja kosong!&quot;);



  const phoneNumber = &quot;628123456789&quot;; // Ganti nomor WA di sini

  let text = &quot;Halo, saya ingin memesan:\\n\\n&quot;;

  cart.forEach(item =\&gt; {

    text += \`- ${item.name} (${item.qty}x) = Rp ${(item.price \* item.qty).toLocaleString('id-ID')}\\n\`;

  });



  const total = cart.reduce((acc, item) =\&gt; acc + (item.price \* item.qty), 0);

  text += \`\\n\*Total Bayar: Rp ${total.toLocaleString('id-ID')}\*\`;

  window.open(\`https://wa.me/${phoneNumber}?text=${encodeURIComponent(text)}\`, '\_blank');

}

renderProducts();
</code></pre>
<p>&lt;/script&gt;</p>
<p>&lt;/body&gt;</p>
<p>&lt;/html&gt;</p>
